    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    struct flow_tuple key = {};
    key.saddr = ip->saddr;
    key.daddr = ip->daddr;
    key.proto = ip->protocol;

    if (ip->protocol == IPPROTO_TCP) {
        unsigned int ip_hdr_len = ip->ihl * 4;
        if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
            return XDP_PASS;
        struct tcphdr *tcp = (void *)ip + ip_hdr_len;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        key.sport = tcp->source;
        key.dport = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        unsigned int ip_hdr_len = ip->ihl * 4;
        if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
            return XDP_PASS;
        struct udphdr *udp = (void *)ip + ip_hdr_len;
        if ((void *)(udp + 1) > data_end)
            return XDP_PASS;
        key.sport = udp->source;
        key.dport = udp->dest;
    } else {
        return XDP_PASS;
    }

    __u64 pkt_len = (__u64)data_end - (__u64)data;
    struct flow_stats *stats = bpf_map_lookup_elem(&flow_metrics_2, &key);
    if (stats) {
        __sync_fetch_and_add(&stats->packets, 1);
        __sync_fetch_and_add(&stats->bytes, pkt_len);
        stats->last_seen = bpf_ktime_get_ns();
    } else {
        struct flow_stats initial = {
            .packets = 1,
            .bytes = pkt_len,
            .last_seen = bpf_ktime_get_ns(),
        };
        bpf_map_update_elem(&flow_metrics_2, &key, &initial, BPF_ANY);
    }

    return XDP_PASS;
}

